void convLayer_backward_x_grad(int M, int C, int H_in, int W_in, int K,

                             float* dE_dY, float* W, float* dE_dX) {

    int H_out = H_in - K + 1;

    int W_out = W_in - K + 1;

    for(int c = 0;  c < C; c++)

        for(int h = 0; h < H_in; h++)

            for(int w = 0; w < W_in; w++)

                dE_dX[c, h, w] = 0;

    for(int m = 0;  m < M;  m++)

        for(int h = 0; h < H-1; h++)

            for(int w = 0; w < W-1; w++)

                for(int c = 0;  c < C; c++)

                    for(int p = 0; p < K; p++)

                        for(int q = 0; q < K; q++)

